var o=[{title:`Estime o seu alcance acima da cabeça`,text:`Fique na superfície em que vai treinar e estique os braços naturalmente acima da cabeça. Depois acrescente a altura do haltere, da kettlebell, da barra ou de outro implemento acima das suas mãos. Deixe espaço para um movimento controlado, para que o objeto nunca fique mesmo a rasar o teto.`},{title:`O movimento precisa de mais do que a altura em pé`,text:`Os saltos acrescentam deslocamento vertical, e uma corda de saltar passa por cima da cabeça. As barras fixas precisam de espaço acima da barra para a cabeça e abaixo para os pés, e as barras de aro de porta também precisam de uma folga segura no ponto onde se fixam. Ventoinhas de teto, luzes, canos e vigas à vista podem reduzir a altura que realmente pode usar.`},{title:`Teste o movimento sem carga`,text:`Se o teto parecer suficientemente alto, ensaie o movimento sem carga e verifique o ponto mais alto a partir de uma posição segura. Nunca teste levantando algo pesado em direção a um teto baixo. Mesmo uma pessoa baixa pode precisar de mais espaço do que o esperado, porque o implemento se desloca acima das mãos.`},{title:`Substituições práticas`,text:`Sob um teto baixo, os press no chão podem substituir os press acima da cabeça, e as remadas podem substituir as barras fixas se a instalação ou a folga da barra for inadequada. Para o condicionamento, escolha a marcha, as subidas a um degrau ou o shadow boxing em vez da corda de saltar ou dos polichinelos com os braços acima da cabeça. Estas trocas podem não treinar exatamente a mesma ação articular, mas mantêm o objetivo da sessão.`},{title:`Usar o TrainUp`,text:`Indique no Perfil a altura do teto, juntamente com o tamanho do espaço no chão. O plano deixa de fora os exercícios acima da cabeça e de saltos que precisam de mais folga do que a que tem.`}];var s=[{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: segurança e técnica no treino com pesos`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:o,sources:s};export{t as default,o as sections,s as sources};